import csv

SEVERITY_WEIGHT = {"critical": 4, "high": 3, "medium": 2, "low": 1}

def priority(row):
    score = SEVERITY_WEIGHT.get(row["severity"].lower(), 0)
    if row.get("kev", "false").lower() == "true":
        score += 3
    if row.get("internet_exposed", "false").lower() == "true":
        score += 2
    score += int(row.get("asset_criticality", "1")) - 1
    return score

with open("vulnerabilities.csv", newline="", encoding="utf-8") as f:
    rows = list(csv.DictReader(f))
rows.sort(key=priority, reverse=True)
for i, row in enumerate(rows, 1):
    print(i, row["cve"], priority(row), row["asset"], row["severity"])

