from __future__ import annotations

from datetime import datetime, timezone
import json
from pathlib import Path
from typing import Iterable

from .models import Event


def parse_timestamp(value: str) -> datetime:
    if not value or not isinstance(value, str):
        raise ValueError("event timestamp must be a non-empty string")
    normalized = value.replace("Z", "+00:00")
    dt = datetime.fromisoformat(normalized)
    if dt.tzinfo is None:
        raise ValueError("event timestamp must include a timezone")
    return dt.astimezone(timezone.utc)


def normalize_record(record: dict) -> Event:
    timestamp = parse_timestamp(record.get("timestamp"))
    event_type = str(record.get("event_type", "unknown"))
    source = str(record.get("source", "unknown"))
    fields = dict(record)
    return Event(timestamp=timestamp, event_type=event_type, source=source, fields=fields)


def load_jsonl(path: str | Path) -> Iterable[Event]:
    with Path(path).open("r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, 1):
            stripped = line.strip()
            if not stripped:
                continue
            try:
                record = json.loads(stripped)
            except json.JSONDecodeError as exc:
                raise ValueError(f"invalid JSON on line {line_number}") from exc
            if not isinstance(record, dict):
                raise ValueError(f"line {line_number} must contain a JSON object")
            yield normalize_record(record)

from __future__ import annotations

import re
from typing import Any

from .models import Condition, Event, Rule


def get_field(event: Event, field: str) -> Any:
    if field == "event_type":
        return event.event_type
    if field == "source":
        return event.source
    if field == "timestamp":
        return event.timestamp
    current: Any = event.fields
    for part in field.split("."):
        if not isinstance(current, dict) or part not in current:
            return None
        current = current[part]
    return current


def evaluate_condition(event: Event, condition: Condition) -> bool:
    actual = get_field(event, condition.field)
    expected = condition.value
    op = condition.operator
    if op == "eq":
        return actual == expected
    if op == "contains":
        return isinstance(actual, str) and str(expected) in actual
    if op == "in":
        return actual in expected
    if op == "regex":
        return isinstance(actual, str) and re.search(str(expected), actual) is not None
    if op == "gte":
        return isinstance(actual, (int, float)) and actual >= expected
    if op == "lte":
        return isinstance(actual, (int, float)) and actual <= expected
    raise ValueError(f"unsupported operator: {op}")


def rule_matches(event: Event, rule: Rule) -> tuple[bool, str]:
    results = [evaluate_condition(event, c) for c in rule.conditions]
    matched = all(results) if rule.condition_mode == "all" else any(results)
    reason = ", ".join(f"{c.field} {c.operator} {c.value!r}" for c in rule.conditions)
    return matched, reason


def rule_from_dict(data: dict) -> Rule:
    conditions = tuple(Condition(c["field"], c["operator"], c.get("value")) for c in data.get("conditions", []))
    return Rule(
        rule_id=data["rule_id"],
        name=data["name"],
        severity=data["severity"],
        conditions=conditions,
        condition_mode=data.get("condition_mode", "all"),
        description=data.get("description", ""),
    )

def load_rules(path: str) -> list[Rule]:
    import json
    with open(path, encoding="utf-8") as handle:
        data = json.load(handle)
    if not isinstance(data, list):
        raise ValueError("rules file must contain a JSON array")
    return [rule_from_dict(item) for item in data]

from __future__ import annotations

from dataclasses import dataclass
import hashlib
from pathlib import Path

from .models import Event


@dataclass(frozen=True)
class IOCSet:
    ips: frozenset[str]
    domains: frozenset[str]
    sha256: frozenset[str]


def _normalize_domain(value: str) -> str:
    return value.strip().lower().rstrip(".")


def load_iocs(path: str | Path) -> IOCSet:
    ips: set[str] = set()
    domains: set[str] = set()
    hashes: set[str] = set()
    with Path(path).open(encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            kind, value = [part.strip() for part in line.split(",", 1)]
            if kind == "ip":
                ips.add(value)
            elif kind == "domain":
                domains.add(_normalize_domain(value))
            elif kind == "sha256":
                hashes.add(value.lower())
            else:
                raise ValueError(f"unsupported IOC type: {kind}")
    return IOCSet(frozenset(ips), frozenset(domains), frozenset(hashes))


def match_iocs(event: Event, iocs: IOCSet) -> list[str]:
    matches: list[str] = []
    ip_values = {event.fields.get("src_ip"), event.fields.get("dst_ip")} - {None}
    for value in ip_values:
        if value in iocs.ips:
            matches.append(f"ip:{value}")
    domain = event.fields.get("domain")
    if isinstance(domain, str) and _normalize_domain(domain) in iocs.domains:
        matches.append(f"domain:{_normalize_domain(domain)}")
    digest = event.fields.get("sha256")
    if isinstance(digest, str) and digest.lower() in iocs.sha256:
        matches.append(f"sha256:{digest.lower()}")
    return matches


def sha256_file(path: str | Path) -> str:
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

SEVERITY_BASE = {"low": 1, "medium": 3, "high": 5, "critical": 7}


def score(severity: str, ioc_matches: int = 0, auth_failure: bool = False) -> int:
    value = SEVERITY_BASE.get(severity.lower(), 0)
    value += min(ioc_matches, 3) * 2
    if auth_failure:
        value += 1
    return value


def priority_label(value: int) -> str:
    if value >= 9:
        return "critical"
    if value >= 6:
        return "high"
    if value >= 3:
        return "medium"
    return "low"

