from datetime import datetime, timezone

from secops_triage.models import Condition, Event, Rule
from secops_triage.rules import evaluate_condition, rule_matches


def event():
    return Event(datetime(2026, 9, 7, 9, tzinfo=timezone.utc), "authentication", "test", {"outcome":"failure", "user":"analyst1", "count":3})


def test_eq_condition():
    assert evaluate_condition(event(), Condition("outcome", "eq", "failure"))


def test_contains_condition():
    assert evaluate_condition(event(), Condition("user", "contains", "analyst"))


def test_rule_all_mode():
    rule = Rule("R1", "Failure", "medium", (Condition("event_type", "eq", "authentication"), Condition("outcome", "eq", "failure")))
    matched, _ = rule_matches(event(), rule)
    assert matched
